export type Reason =
  | {
      reason: "empty_changeset";
    }
  | {
      base: Seq;
      head: Seq;
      reason: "base_ahead";
    }
  | {
      reason: "already_committed";
      seq: Seq;
    }
  | {
      identity: IdentityId;
      reason: "identity_exists";
    }
  | {
      reason: "unknown_record";
      record: RecordId;
    }
  | {
      identity: IdentityId;
      reason: "unknown_identity";
    }
  | {
      identity: IdentityId;
      merged_into: IdentityId;
      reason: "identity_not_active";
    }
  | {
      actual?: IdentityId | null;
      expected?: IdentityId | null;
      reason: "stale_assignment";
      record: RecordId;
    }
  | {
      reason: "no_change";
      record: RecordId;
    }
  | {
      identity: IdentityId;
      identity_type: EntityType;
      reason: "entity_type_mismatch";
      record: RecordId;
      record_type: EntityType;
    }
  | {
      first_op: number;
      reason: "record_assigned_twice";
      record: RecordId;
    }
  | {
      identity: IdentityId;
      reason: "merge_into_itself";
    }
  | {
      from: IdentityId;
      from_type: EntityType;
      into: IdentityId;
      into_type: EntityType;
      reason: "identity_type_mismatch";
    }
  | {
      base: Seq;
      changed: Seq;
      identity: IdentityId;
      reason: "stale_merge";
    }
  | {
      first_op: number;
      identity: IdentityId;
      reason: "members_moved_twice";
    }
  | {
      identity: IdentityId;
      reason: "identity_is_active";
    }
  | {
      first_op: number;
      identity: IdentityId;
      reason: "identity_changed_twice";
    }
  | {
      reason: "same_record";
      record: RecordId;
    }
  | {
      a: RecordId;
      a_type: EntityType;
      b: RecordId;
      b_type: EntityType;
      reason: "constraint_across_types";
    }
  | {
      a: RecordId;
      b: RecordId;
      kind: ConstraintKind;
      reason: "constraint_exists";
    }
  | {
      a: RecordId;
      b: RecordId;
      kind: ConstraintKind;
      reason: "unknown_constraint";
    }
  | {
      a: RecordId;
      b: RecordId;
      first_op: number;
      kind: ConstraintKind;
      reason: "constraint_changed_twice";
    }
  | {
      a: RecordId;
      b: RecordId;
      identity_a?: IdentityId | null;
      identity_b?: IdentityId | null;
      kind: ConstraintKind;
      reason: "constraint_violated";
    };

/**
 * `POST /v1/runs/{run}/reconcile`. The body may be left out.
 */
export interface ReconcileRequest {
  /**
   * Commit the draft (the default), or store it for review.
   */
  commit?: boolean | null;
}

/**
 * A record as it was ingested, and the identity it belongs to now.
 */
export interface RecordEntry {
  entity_type: EntityType;
  /**
   * Where in the source the record was found, if the source said.
   */
  evidence?: unknown;
  id: RecordId;
  /**
   * `None` while no changeset has placed it.
   */
  identity?: IdentityId | null;
  ingest_run: RunId;
  ingested_at: string;
  /**
   * The row's key within its source, if it had one.
   */
  key?: string | null;
  /**
   * What a person would call it: its value of the feature its type
   * names as the label. `None` when the type names none, or the record
   * has no value there.
   */
  label?: string | null;
  /**
   * The attributes exactly as received.
   */
  payload: unknown;
  source: string;
  /**
   * The version that replaced this one, if the source has sent the row
   * again with other content.
   */
  superseded_by?: RecordId | null;
  /**
   * The version of the row this one replaced: what the source held under
   * the same key before.
   */
  supersedes?: RecordId | null;
}

/**
 * Identifies a record. Derived by the engine from the record's source, key and content.
 */
export type RecordId = string;

export interface RecordList {
  /**
   * Pass as `after` for the next page. `null` on the last page.
   */
  next?: RecordId | null;
  records: RecordEntry[];
}

/**
 * A judgement as a run stored it.
 */
export interface RecordedJudgement {
  /**
   * What the strategy kept with the judgement. The built-in `rules`
   * keeps the names of the rules that held.
   */
  detail?: unknown;
  /**
   * On the strategy's own scale.
   */
  score?: number | null;
  verdict: Verdict;
}

/**
 * `POST /v1/drafts/{draft}/reject`. The body may be left out.
 */
export interface RejectDraftRequest {
  reason?: string | null;
}

/**
 * Why a changeset was not accepted. `op_index` and `op` name the operation
 * that conflicted, and are `None` when the changeset as a whole is at fault.
 */
export interface Rejection {
  op?: Op | null;
  op_index?: number | null;
  reason: Reason;
}

/**
 * A review item with what a reviewer reads to decide it: the records
 * it holds back, the identities they matched, what was judged between
 * them, and what was already decided about them.
 */
export interface ReviewCase {
  /**
   * The identities the item names, as they stand now, ordered by ID. One
   * that was merged away since is shown as the identity that stands for
   * it, so there may be fewer than the item names.
   */
  candidates: Candidate[];
  /**
   * The constraints in force that bear on the decision, oldest first:
   * those that name one of the item's records, and those between
   * members of two of the candidates. A changeset that would break one
   * is refused, so a `cannot_link` between two candidates means they
   * cannot be merged, and one between a record and a member of a
   * candidate means it cannot be placed there.
   */
  constraints: CaseConstraint[];
  item: ReviewEntry;
  /**
   * What the latest run to judge each pair made of it, for every pair of
   * one of the item's records with another of them or with a member
   * of a candidate. Only runs that were reconciled count.
   */
  judgements: PairJudgement[];
  /**
   * The records the item names, as they are now, in the item's
   * order.
   */
  records: RecordEntry[];
}

/**
 * A review item as the store keeps it.
 */
export interface ReviewEntry {
  /**
   * Dismissed: who closed it, when and why.
   */
  dismissed?: Dismissal | null;
  entity_type: EntityType;
  id: number;
  /**
   * The identities they matched. Empty when the conflict is among the
   * records themselves.
   */
  identities: IdentityId[];
  kind: ReviewKind;
  /**
   * The records left without an identity.
   */
  records: RecordId[];
  /**
   * Resolved: the changeset after which every record had an identity.
   */
  resolved_seq?: Seq | null;
  /**
   * The reconcile run that raised it.
   */
  run: RunId;
  status: ReviewStatus;
  /**
   * Superseded: the reconcile run that raised it again in another form.
   */
  superseded_by?: RunId | null;
}

/**
 * Something the reconciler would not decide. The records named are left
 * without an identity.
 */
export type ReviewItem =
  | {
      identities: IdentityId[];
      kind: "possible_merge";
      records: RecordId[];
    }
  | {
      identity?: IdentityId | null;
      kind: "conflict";
      records: RecordId[];
    };

export type ReviewKind = "possible_merge" | "conflict";

export interface ReviewList {
  items: ReviewEntry[];
}

export type ReviewStatus = "open" | "resolved" | "superseded" | "dismissed";

/**
 * The project's rules applied to a pair as it is now.
 */
export interface RuleReading {
  block: RuleResult[];
  /**
   * Whether a block rule holds, so that a run of the rules would compare
   * the two.
   */
  candidate: boolean;
  /**
   * What SQL said when it refused to apply the `no_match` and `match`
   * rules to the pair, as it refuses the cast of a value that does not
   * convert. Their `holds` is then `null`. A run applies those rules
   * only to pairs a block rule found, so a rule may rely on what the
   * block rules let through and fail on a pair they did not. On a
   * candidate pair, a run of the rules fails the same way.
   */
  failed?: string | null;
  match: RuleResult[];
  no_match: RuleResult[];
  /**
   * What a run of the rules would judge. `null` when the pair is not a
   * candidate, and when no `no_match` or `match` rule holds.
   */
  verdict?: Verdict | null;
}

/**
 * One rule applied to a pair.
 */
export interface RuleResult {
  /**
   * Whether the predicate holds. `null` when it cannot be decided, which
   * is what SQL makes of a comparison with a feature that is null, and
   * for a `no_match` or `match` rule when those `failed`. A rule that
   * cannot be decided does not hold.
   */
  holds?: boolean | null;
  name: string;
  /**
   * The rule's SQL, over the feature rows `l` and `r`.
   */
  predicate: string;
}

/**
 * A run as a caller sees it.
 */
export interface RunEntry {
  /**
   * The entity type an ingest or a match run is about.
   */
  entity_type?: EntityType | null;
  /**
   * Why a failed run failed.
   */
  error?: string | null;
  /**
   * What an extract run reported when it finished.
   */
  extraction?: ExtractReport | null;
  /**
   * The extractor of an extract run, and of the ingest run that stored
   * what it found.
   */
  extractor?: ExtractorRef | null;
  finished_at?: string | null;
  /**
   * What an ingest run reported when it finished. The run stored rows,
   * documents, or the mentions an extract run found.
   */
  ingest?: IngestReport | null;
  kind: RunKind;
  /**
   * What a match run reported when it was reconciled. `committed` is
   * filled in once its draft is committed.
   */
  resolution?: TypeResolution | null;
  run: RunId;
  started_at: string;
  status: RunStatus;
  /**
   * The strategy of a match run.
   */
  strategy?: StrategyRef | null;
}

/**
 * Identifies a run of the engine: an ingest, a match or a reconcile.
 */
export type RunId = number;

export type RunKind = "ingest" | "extract" | "match" | "reconcile";

export interface RunList {
  runs: RunEntry[];
}

/**
 * A run, as the response of a call that started one or read one. `run` is
 * `null` when there was nothing to do, so no run was started.
 */
export interface RunResponse {
  run?: RunEntry | null;
}

/**
 * How far a run has got.
 *
 * Only `running` means the engine is at work. An `open` or `drafted` match
 * run waits for someone else, and stays as it is across a restart. A run
 * found `running` when a store is opened was interrupted, and is recorded as
 * `failed`.
 */
export type RunStatus = "running" | "open" | "drafted" | "succeeded" | "failed";

/**
 * What runs a strategy file. The file's extension decides.
 */
export type Runtime = "python" | "typescript";

/**
 * A position in the changeset log. The first committed changeset is 1, and 0
 * is the empty log.
 */
export type Seq = number;

/**
 * `GET /auth/session`: who the caller is signed in as.
 */
export interface SessionState {
  /**
   * A development server: nobody signs in, and whoever opens it is the
   * `dev` account.
   */
  dev: boolean;
  person?: Person | null;
  /**
   * No admin can sign in yet. The server printed a link when it started
   * that makes the first account.
   */
  setup: boolean;
}

/**
 * `POST /auth/setup`: make the first account, an admin, with the code from
 * the link the server printed.
 */
export interface SetupRequest {
  code: string;
  name: string;
  password: string;
  username: string;
}

/**
 * `POST /auth/sign-in`.
 */
export interface SignInRequest {
  password: string;
  username: string;
}

/**
 * How many records a source gave.
 */
export interface SourceCount {
  records: number;
  source: string;
}

/**
 * What one source gave of an entity type.
 */
export interface SourceInfo {
  /**
   * When the latest of them was ingested.
   */
  last_ingested_at: string;
  /**
   * Counting each version of a row.
   */
  records: number;
  source: string;
  /**
   * Those of them no changeset has placed.
   */
  unassigned: number;
}

/**
 * What a split did.
 */
export interface SplitReport {
  changeset: Changeset;
  committed: Committed;
  /**
   * The new identity.
   */
  identity: IdentityId;
  /**
   * The identity that was split. It keeps its ID and the larger side.
   */
  kept: IdentityId;
  /**
   * The records that moved to the new identity, in order.
   */
  moved: RecordId[];
}

/**
 * `POST /v1/identities/{identity}/split`: divide an identity in two.
 */
export interface SplitRequest {
  /**
   * The log position the identity was read at. With it, the split is
   * refused if the identity's members changed after that: which side
   * moves depends on all of them. Without it, the split is made of the
   * members the identity has now.
   */
  base?: Seq | null;
  /**
   * Record a `cannot_link` constraint between the two sides (the
   * default), so that nothing puts them back together unnoticed.
   */
  keep_apart?: boolean | null;
  reason?: string | null;
  /**
   * The records on one side. The rest of the identity's members are
   * the other side. The larger side keeps the ID, the side not named here
   * on a tie.
   */
  records: RecordId[];
}

/**
 * `POST /v1/runs`: match the new records of one entity type.
 */
export interface StartRunRequest {
  /**
   * With a strategy the server runs: commit the draft (the default), or
   * store it for review. A run that waits for judgements is told this
   * when it is reconciled.
   */
  commit?: boolean | null;
  entity_type: EntityType;
  /**
   * Match every record of the type again, not only the new ones.
   * Records that have an identity keep it: where the strategy
   * disagrees with the identities as they are, the run's `resolution`
   * lists `suggestions`.
   */
  rematch?: boolean | null;
  /**
   * Who judges. Left out, or named `rules`, the server runs the
   * project's SQL rules and reconciles. The name of one of the project's
   * user-code strategies runs that code on the server and reconciles;
   * `GET /v1/info` lists them. Any other name starts a run that waits
   * for the caller's judgements: the server runs no code it was not
   * built with, whatever is named here.
   *
   * A `version` given with a project strategy must be the hash the
   * project was built with.
   */
  strategy?: StrategyRef | null;
  /**
   * How long the call waits for the run, in milliseconds. If the run is
   * still in progress then, the response has status 202 and the run as
   * far as it has got.
   */
  wait_ms?: number | null;
}

/**
 * What a store holds.
 */
export interface StoreInfo {
  /**
   * Documents held, counting each version.
   */
  documents?: number;
  engine_version: string;
  entity_types: TypeInfo[];
  /**
   * The project's extractors. Empty when the engine runs without a
   * manifest.
   */
  extractors?: Extractor[];
  format_version: string;
  /**
   * The position of the last committed changeset.
   */
  head: Seq;
  /**
   * The hash of the manifest the store was last applied with.
   */
  manifest_hash?: string | null;
}

/**
 * A strategy that is user code: a file the engine runs as a child process.
 * The engine runs the file only while it still has this hash.
 */
export interface Strategy {
  /**
   * The file, as a path from the project directory with `/` between its
   * parts.
   */
  file: string;
  /**
   * SHA-256 of the file and of every file in the directory that shares
   * its name. It is recorded as the strategy's version with each run.
   */
  hash: string;
  name: string;
  runtime: Runtime;
}

/**
 * Names the strategy that produces a match run's judgements.
 */
export interface StrategyRef {
  name: string;
  version?: string | null;
}

export interface SuggestedMerge {
  /**
   * The two identities, the smaller ID first.
   */
  identities: [IdentityId, IdentityId];
  /**
   * Pairs of their members the strategy judged `match`.
   */
  matches: number;
  /**
   * Pairs of their members the strategy judged `no_match`. More than
   * none means the strategy contradicts itself about these two.
   */
  no_matches: number;
}

export interface SuggestedSplit {
  identity: IdentityId;
  /**
   * Pairs of its members the strategy judged `match`.
   */
  matches: number;
  /**
   * Pairs of its members the strategy judged `no_match`.
   */
  no_matches: number;
}

/**
 * What a rematch would change about existing identities if judgements were
 * allowed to. Nothing here was applied: a reviewer who agrees merges or
 * splits with a changeset.
 */
export interface Suggestions {
  /**
   * Pairs of identities with a `match` between their members, ordered by
   * their IDs.
   */
  merges: SuggestedMerge[];
  /**
   * Identities with a `no_match` between two of their members, ordered
   * by ID.
   */
  splits: SuggestedSplit[];
}

export interface TypeInfo {
  /**
   * How many times the declaration has been applied in a new form.
   */
  declaration_version: number;
  /**
   * The columns of the feature table, as the manifest declares them.
   * Empty when the engine runs without a manifest.
   */
  features: FeatureColumn[];
  identities: number;
  name: EntityType;
  /**
   * The draft that waits for a decision, if there is one.
   */
  open_draft?: ChangesetId | null;
  open_review_items: number;
  records: number;
  /**
   * The sources the records came from, by name.
   */
  sources: SourceInfo[];
  /**
   * The project's user-code strategies for the type. The built-in
   * `rules` is always there and is not listed.
   */
  strategies?: Strategy[];
  /**
   * Records no changeset has placed.
   */
  unassigned: number;
}

export interface TypeResolution {
  /**
   * Distinct candidate pairs.
   */
  candidates: number;
  /**
   * The changeset, once it is committed. `None` when there was nothing to
   * commit, and while a draft waits.
   */
  committed?: Committed | null;
  /**
   * The draft that was stored for review, if the run was asked to leave
   * one. It is named by its changeset ID.
   */
  draft?: ChangesetId | null;
  entity_type: EntityType;
  identities_created: number;
  judgements: JudgementCounts;
  match_run: RunId;
  /**
   * Records the run examined: those ingested since the last run, and
   * those an earlier run left for review.
   */
  new_records: number;
  reconcile_run: RunId;
  records_assigned: number;
  /**
   * Examined records left without an identity. Each is named in
   * `review`.
   */
  records_unassigned: number;
  /**
   * How many of them an earlier run had left for review.
   */
  reexamined: number;
  /**
   * What the run would not decide. The store keeps these as review items.
   */
  review: ReviewItem[];
  /**
   * Where the strategy disagrees with the identities as they are. Only a
   * rematch has these: no other run judges pairs of records that
   * both have an identity.
   */
  suggestions?: Suggestions | null;
}

/**
 * `POST /v1/changesets/{seq}/undo`: take back the changeset at a log
 * position with a new changeset.
 */
export interface UndoRequest {
  /**
   * Commit the undo (the default), or only validate it and return it.
   */
  commit?: boolean | null;
  reason?: string | null;
}

export type Verdict = "match" | "no_match" | "unsure";
